
/* Minimal JSZip store-only for Enxame - supports file(name, Blob|string|Uint8Array) + generateAsync */
(function(global){
  function crc32(buf){
    let table = crc32.table;
    if(!table){
      table = new Uint32Array(256);
      for(let i=0;i<256;i++){
        let c=i;
        for(let j=0;j<8;j++) c = (c & 1) ? (0xEDB88320 ^ (c>>>1)) : (c>>>1);
        table[i]=c;
      }
      crc32.table=table;
    }
    let crc=0 ^ (-1);
    for(let i=0;i<buf.length;i++) crc = (crc>>>8) ^ table[(crc ^ buf[i]) & 0xFF];
    return (crc ^ (-1)) >>> 0;
  }
  async function blobToUint8(blob){
    const ab = await blob.arrayBuffer();
    return new Uint8Array(ab);
  }
  class JSZip {
    constructor(){ this.files=[]; }
    file(name, data){
      this.files.push({name, data});
      return this;
    }
    folder(name){
      // noop for flat, but keep prefix
      const self=this;
      return {
        file: (n,d) => self.file(name + '/' + n, d)
      };
    }
    async generateAsync(opts){
      opts = opts||{type:'blob'};
      const fileDatas = [];
      for(const f of this.files){
        let u8;
        if(f.data instanceof Blob){
          u8 = await blobToUint8(f.data);
        } else if(typeof f.data === 'string'){
          u8 = new TextEncoder().encode(f.data);
        } else if(f.data instanceof Uint8Array){
          u8 = f.data;
        } else if(f.data instanceof ArrayBuffer){
          u8 = new Uint8Array(f.data);
        } else {
          u8 = new TextEncoder().encode(JSON.stringify(f.data));
        }
        fileDatas.push({name:f.name, data:u8, crc:crc32(u8)});
      }
      // Build zip
      const parts=[];
      let offset=0;
      const central=[];
      for(const fd of fileDatas){
        const nameBytes = new TextEncoder().encode(fd.name);
        const header = new Uint8Array(30 + nameBytes.length);
        const view = new DataView(header.buffer);
        view.setUint32(0, 0x04034b50, true); // local header
        view.setUint16(4, 20, true); // version
        view.setUint16(6, 0, true); // flags
        view.setUint16(8, 0, true); // store
        view.setUint16(10, 0, true); // time
        view.setUint16(12, 0, true); // date
        view.setUint32(14, fd.crc, true);
        view.setUint32(18, fd.data.length, true);
        view.setUint32(22, fd.data.length, true);
        view.setUint16(26, nameBytes.length, true);
        view.setUint16(28, 0, true);
        header.set(nameBytes, 30);
        parts.push(header);
        parts.push(fd.data);
        // central dir
        const cd = new Uint8Array(46 + nameBytes.length);
        const cdv = new DataView(cd.buffer);
        cdv.setUint32(0, 0x02014b50, true);
        cdv.setUint16(4, 20, true);
        cdv.setUint16(6, 20, true);
        cdv.setUint16(8, 0, true);
        cdv.setUint16(10, 0, true);
        cdv.setUint16(12, 0, true);
        cdv.setUint16(14, 0, true);
        cdv.setUint32(16, fd.crc, true);
        cdv.setUint32(20, fd.data.length, true);
        cdv.setUint32(24, fd.data.length, true);
        cdv.setUint16(28, nameBytes.length, true);
        cdv.setUint16(30, 0, true);
        cdv.setUint16(32, 0, true);
        cdv.setUint16(34, 0, true);
        cdv.setUint16(36, 0, true);
        cdv.setUint32(38, 0, true);
        cdv.setUint32(42, offset, true);
        cd.set(nameBytes, 46);
        central.push(cd);
        offset += header.length + fd.data.length;
      }
      let centralOffset = offset;
      let centralSize = 0;
      for(const c of central){ centralSize+=c.length; parts.push(c); }
      // EOCD
      const eocd = new Uint8Array(22);
      const eocdv = new DataView(eocd.buffer);
      eocdv.setUint32(0, 0x06054b50, true);
      eocdv.setUint16(4, 0, true);
      eocdv.setUint16(6, 0, true);
      eocdv.setUint16(8, fileDatas.length, true);
      eocdv.setUint16(10, fileDatas.length, true);
      eocdv.setUint32(12, centralSize, true);
      eocdv.setUint32(16, centralOffset, true);
      eocdv.setUint16(20, 0, true);
      parts.push(eocd);
      const totalLen = parts.reduce((s,p)=>s+p.length,0);
      const out = new Uint8Array(totalLen);
      let pos=0;
      for(const p of parts){ out.set(p,pos); pos+=p.length; }
      if(opts.type==='blob') return new Blob([out], {type:'application/zip'});
      if(opts.type==='uint8array') return out;
      return out;
    }
  }
  global.JSZip = JSZip;
})(typeof window !== 'undefined' ? window : this);
